# Security Review & Hardened Implementation

Reviewing your `server.py` against MCP server hardening standards reveals several critical vulnerabilities that would expose your office network, local filesystem, and backend database to attack if deployed as-is.

## Attack Surface & Vulnerability Summary

1. **Host Binding (`host="0.0.0.0"`) & No Authentication**: The server listens on all network interfaces without any authentication or transport encryption. Anyone on your office network can connect to it.
2. **Path Traversal (`read_doc`)**: Using `os.path.join(DOCS, path)` without validation allows path traversal attacks (e.g., passing `../../etc/passwd`), exposing arbitrary files readable by the process user.
3. **SSRF (`fetch`)**: The `fetch` tool accepts any URL without restriction, allowing Server-Side Request Forgery against cloud metadata endpoints (`169.254.169.254`) and internal microservices.
4. **Remote Code Execution (`grep_logs`)**: Using `shell=True` with unvalidated user input (`pattern`) allows arbitrary shell command injection.
5. **Token Passthrough (`list_repos`)**: The server accepts a raw user token and forwards it downstream to GitHub, violating the MCP specification against token passthrough.
6. **Information Disclosure (`report`)**: On database query errors, the server returns full Python stack traces containing database connection strings (`DB_URL`).

---

## Hardened Implementation

Below is the fully hardened version of `server.py`. It switches to Streamable HTTP with secure defaults (binding to loopback by default, requiring a bearer token, validating `Origin`), locks down filesystem access, sanitizes URL fetching and subprocess execution, and handles errors safely.

# file: server.py
```python
import hmac
import ipaddress
import os
import re
import socket
import subprocess
import urllib.parse
import urllib.request
from typing import Optional

from fastapi import FastAPI, Header, HTTPException, Request, Response
from fastapi.responses import JSONResponse
from mcp.server.fastmcp import FastMCP

from db import run_query

# 1. Configuration & Secrets
MCP_TOKEN = os.environ.get("MCP_TOKEN")
if not MCP_TOKEN:
    raise RuntimeError("CRITICAL: MCP_TOKEN environment variable must be set.")

DOCS = os.path.realpath("/srv/docs")
DB_URL = os.environ.get("DATABASE_URL")
if not DB_URL:
    raise RuntimeError("CRITICAL: DATABASE_URL environment variable must be set.")

# Initialize FastMCP
mcp = FastMCP("team-tools")


# 2. Tool Implementations with Hardening

@mcp.tool()
def read_doc(path: str) -> str:
    """Read a document from the shared docs folder safely.

    Args:
        path: Relative path to the document within the docs root.
    """
    if not path or len(path) > 256:
        raise ValueError("Invalid path length.")

    # Resolve and ensure the path stays within DOCS (prevents path traversal)
    target_path = os.path.realpath(os.path.join(DOCS, path))
    if not target_path.startswith(DOCS + os.sep) and target_path != DOCS:
        raise ValueError("Access denied: Path is outside the allowed documents directory.")

    if not os.path.isfile(target_path):
        raise ValueError("Document not found.")

    # Check file size (e.g., max 10MB)
    if os.path.getsize(target_path) > 10 * 1024 * 1024:
        raise ValueError("Document is too large to read.")

    with open(target_path, "r", encoding="utf-8", errors="replace") as f:
        return f.read()


@mcp.tool()
def fetch(url: str) -> str:
    """Fetch a web page so the assistant can read it (restricted to public HTTP/HTTPS URLs)."""
    parsed = urllib.parse.urlparse(url)
    if parsed.scheme not in ("http", "https"):
        raise ValueError("Only http and https schemes are permitted.")

    hostname = parsed.hostname
    if not hostname:
        raise ValueError("Invalid URL: missing hostname.")

    try:
        # Resolve IP to block internal networks, loopback, and metadata services
        ip_str = socket.gethostbyname(hostname)
        ip = ipaddress.ip_address(ip_str)
        if ip.is_private or ip.is_loopback or ip.is_link_local or ip.is_multicast or ip.is_reserved:
            raise ValueError("Access denied: Target IP address is restricted.")
    except socket.gaierror:
        raise ValueError("Failed to resolve hostname.")
    except ValueError as e:
        if "restricted" in str(e) or "IP address" in str(e):
            raise
        raise ValueError("Invalid target address.")

    req = urllib.request.Request(
        url,
        headers={"User-Agent": "MCPTeamToolsBot/1.0"}
    )
    try:
        with urllib.request.urlopen(req, timeout=10) as response:
            # Limit read size (e.g., 2MB)
            data = response.read(2 * 1024 * 1024)
            return data.decode("utf-8", errors="replace")
    except Exception:
        raise ValueError("Failed to fetch the requested URL safely.")


@mcp.tool()
def grep_logs(pattern: str) -> str:
    """Search today's application log for a specific pattern safely."""
    if not pattern or len(pattern) > 100:
        raise ValueError("Pattern must be between 1 and 100 characters.")

    # Restrict allowed characters to prevent unexpected matching behavior
    if not re.match(r'^[\w\-. ]+$', pattern):
        raise ValueError("Pattern contains disallowed characters.")

    log_path = "/var/log/app.log"
    if not os.path.isfile(log_path):
        raise ValueError("Log file is not available.")

    # Pass arguments as a list with shell=False to prevent command injection
    try:
        result = subprocess.run(
            ["grep", pattern, log_path],
            capture_output=True,
            text=True,
            timeout=5,
            check=False
        )
        if result.returncode > 1:
            return "An error occurred while searching logs."
        return result.stdout or "No matches found."
    except subprocess.TimeoutExpired:
        raise ValueError("Log search timed out.")


@mcp.tool()
def report(name: str) -> str:
    """Run one of the saved reports."""
    if not name or not re.match(r'^[a-zA-Z0-9_\-]+$', name):
        raise ValueError("Invalid report name format.")

    try:
        return run_query(DB_URL, name)
    except Exception:
        # Return a safe error message without leaking stack traces or database URLs
        return "An error occurred while executing the report. Please contact the administrator."


# 3. HTTP Transport Hardening & ASGI App Wrap

# FastMCP provides an underlying Starlette/FastAPI app when using streamable-http.
app = mcp.create_app(transport="streamable-http")

@app.middleware("http")
async def security_middleware(request: Request, call_next):
    # Validate Origin header to prevent DNS rebinding attacks on localhost/internal servers
    origin = request.headers.get("origin")
    if origin:
        parsed_origin = urllib.parse.urlparse(origin)
        allowed_hosts = {"localhost", "127.0.0.1", "::1"}
        if parsed_origin.hostname not in allowed_hosts:
            return Response("Forbidden Origin", status_code=403)

    # Validate Authorization Bearer token on MCP endpoints
    if request.url.path.startswith("/mcp") or request.method == "POST":
        auth_header = request.headers.get("authorization")
        if not auth_header or not auth_header.startswith("Bearer "):
            return Response("Unauthorized", status_code=401, headers={"WWW-Authenticate": "Bearer"})

        token = auth_header[len("Bearer "):]
        if not hmac.compare_digest(token.encode("utf-8"), MCP_TOKEN.encode("utf-8")):
            return Response("Unauthorized", status_code=401)

    response = await call_next(request)
    return response


if __name__ == "__main__":
    import uvicorn
    # Bind to loopback by default unless explicitly configured otherwise with authentication
    host = os.environ.get("MCP_HOST", "127.0.0.1")
    port = int(os.environ.get("MCP_PORT", 8000))

    if host != "127.0.0.1" and host != "localhost":
        print(f"WARNING: Binding to non-loopback address {host}. Ensure firewall/auth is strictly managed.")

    uvicorn.run(app, host=host, port=port)
